  final note=TextEditingController(),no=TextEditingController();final form=GlobalKey<FormState>();
  final yes=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(decision=='approve'?'Setujui pengajuan':'Tolak pengajuan'),content:SingleChildScrollView(child:Form(key:form,child:Column(mainAxisSize:MainAxisSize.min,children:[Text('${r['nama_lengkap']} • ${r['jumlah_hari']} hari'),const SizedBox(height:12),if(decision=='approve')field(no,'Nomor surat',required:true),field(note,decision=='approve'?'Catatan (opsional)':'Alasan penolakan',required:decision=='reject',lines:3)]))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Batal')),FilledButton(onPressed:(){if(form.currentState!.validate())Navigator.pop(c,true);},child:const Text('Konfirmasi'))]));
