  note.dispose();no.dispose();
 }
 @override Widget build(BuildContext context)=>Remote(key:ValueKey('${month(period)}-$version'),load:()=>widget.api.call('leaves',query:{'month':month(period)}),builder:(d){final rows=records(d['items']);return ListView(padding:const EdgeInsets.all(16),physics:const AlwaysScrollableScrollPhysics(),children:[MonthPicker(value:period,onChanged:(v)=>setState(()=>period=v)),if(!widget.admin)...[Panel(child:info('Saldo tersedia','${d['balance']} hari')),FilledButton.icon(onPressed:()async{await openPage(context,LeaveForm(api:widget.api,balance:number(d['balance'])));if(mounted)setState(()=>version++);},icon:const Icon(Icons.add),label:const Text('Ajukan cuti')),const SizedBox(height:10),const Notice('Saldo dicadangkan saat pengajuan. Penolakan mengembalikan saldo. Tanggal terpisah menjadi beberapa pengajuan pada website.')],if(widget.admin)OutlinedButton.icon(onPressed:()=>exportTable(context,'Rekap Cuti ${month(period)}',rows,['nama_lengkap','tanggal_mulai','tanggal_selesai','jumlah_hari','status'],['Nama','Mulai','Selesai','Hari','Status']),icon:const Icon(Icons.print),label:const Text('Cetak rekap PDF')),heading(widget.admin?'Pengajuan pegawai':'Riwayat pengajuan'),if(rows.isEmpty)const Notice('Belum ada pengajuan pada bulan ini.'),for(final r in rows)Panel(child:ExpansionTile(tilePadding:EdgeInsets.zero,title:Text(widget.admin?'${r['nama_lengkap']}':'${r['tanggal_mulai']} — ${r['tanggal_selesai']}',style:const TextStyle(fontSize:14,fontWeight:FontWeight.bold)),subtitle:Text('${r['jumlah_hari']} hari${widget.admin?' • ${r['tanggal_mulai']}':''}'),trailing:StatusBadge(r['status']),children:[info('Mulai',r['tanggal_mulai']),info('Selesai',r['tanggal_selesai']),info('Alasan',r['alasan']),info('Alamat',r['alamat_cuti']),info('Kontak',r['phone']??'-'),if('${r['catatan_admin']??''}'.isNotEmpty)info('Catatan admin',r['catatan_admin']),if(widget.admin&&r['status']=='pending')Wrap(spacing:8,children:[OutlinedButton(onPressed:()=>review(r,'reject'),child:const Text('Tolak')),FilledButton(onPressed:()=>review(r,'approve'),child:const Text('Setujui'))]),if(widget.admin&&r['status']=='approved')OutlinedButton.icon(onPressed:()async{try{final b=await widget.api.bytes('flutter/cuti_pdf.php',{'id':r['id']});if(context.mounted)await previewPdf(context,b,'Surat-Cuti-${r['id']}.pdf');}catch(e){if(context.mounted)showFailure(context,e);}},icon:const Icon(Icons.print),label:const Text('Cetak surat cuti'))]))]);});
