class LeaveForm extends StatefulWidget{
 final Api api;final int balance;const LeaveForm({super.key,required this.api,required this.balance});
 @override State<LeaveForm> createState()=>_LeaveFormState();
}
class _LeaveFormState extends State<LeaveForm>{
 final form=GlobalKey<FormState>();final dates=<String>{};final reason=TextEditingController(),address=TextEditingController(),phone=TextEditingController(),job=TextEditingController(),service=TextEditingController();bool busy=false;String? error;
 final requestId=List.generate(32,(_)=>'0123456789abcdef'[Random.secure().nextInt(16)]).join();
 @override void dispose(){for(final c in [reason,address,phone,job,service]){c.dispose();}super.dispose();}
 Future<void> choose()async{final d=await showDatePicker(context:context,initialDate:DateTime.now(),firstDate:DateTime.now(),lastDate:DateTime(DateTime.now().year+1,12,31));if(d!=null)setState(()=>dates.add(day(d)));}
 Future<void> submit()async{
  if(!form.currentState!.validate())return;if(dates.isEmpty||dates.length>widget.balance){setState(()=>error='Pilih tanggal sesuai saldo tersedia.');return;}
  setState((){busy=true;error=null;});try{await widget.api.call('leave_create',data:{'request_id':requestId,'dates':dates.toList()..sort(),'reason':reason.text,'leave_address':address.text,'phone':phone.text,'position_name':job.text,'service_period':service.text});if(mounted)Navigator.pop(context);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>busy=false);}
 }
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Pengajuan Cuti')),body:Form(key:form,child:ListView(padding:const EdgeInsets.all(16),children:[if(error!=null)Notice(error!,error:true),Panel(child:Column(children:[info('Jenis cuti','Cuti tahunan'),info('Saldo tersedia','${widget.balance} hari')])),heading('Pilih tanggal satu per satu'),Wrap(spacing:6,children:[for(final d in dates.toList()..sort())InputChip(label:Text(d),onDeleted:busy?null:()=>setState(()=>dates.remove(d))),ActionChip(label:const Text('+ Tanggal'),onPressed:busy?null:choose)]),const SizedBox(height:12),Notice('Dipilih ${dates.length} hari • Sisa setelah dikirim: ${widget.balance-dates.length} hari'),field(reason,'Alasan cuti',required:true,lines:3),field(job,'Jabatan / jenis pekerjaan',required:true),field(service,'Masa kerja',required:true),field(address,'Alamat selama cuti',required:true,lines:2),field(phone,'Nomor telepon',required:true,keyboard:TextInputType.phone),FilledButton(onPressed:busy?null:submit,child:Text(busy?'Mengirim…':'Ajukan cuti'))])));
}
